package registry

import (
	"crypto/ed25519"
	"encoding/base64"
	"encoding/hex"
	"fmt"
	"strings"
	"sync"
)

// OmniviewPublicKeyHex is the hex-encoded Ed25519 public key used to verify plugin signatures.
// Replace this placeholder with the real key generated by `registry-cli keygen`.
var OmniviewPublicKeyHex = "c84100654c6c0d42e8a86f16253a21b7f01b8e914d83ba07ce072f086a8add31"

// AdditionalPublicKeysHex is a comma-separated list of further hex-encoded Ed25519 public keys whose signatures
// are accepted alongside OmniviewPublicKeyHex, for example those of self-hosted marketplaces. Like
// OmniviewPublicKeyHex it can be set at build time with -ldflags -X; AddPublicKey adds keys at runtime.
var AdditionalPublicKeysHex = ""

var (
	keysMu            sync.RWMutex
	omniviewPublicKey ed25519.PublicKey
	additionalKeys    []ed25519.PublicKey
)

func init() {
	key, err := hex.DecodeString(OmniviewPublicKeyHex)
	if err != nil {
		panic(fmt.Sprintf("failed to decode embedded public key: %v", err))
	}
	omniviewPublicKey = ed25519.PublicKey(key)

	for _, h := range strings.Split(AdditionalPublicKeysHex, ",") {
		if h = strings.TrimSpace(h); h == "" {
			continue
		}
		if err := AddPublicKey(h); err != nil {
			panic(fmt.Sprintf("failed to decode embedded additional public key: %v", err))
		}
	}
}

func decodePublicKey(hexKey string) (ed25519.PublicKey, error) {
	key, err := hex.DecodeString(strings.TrimSpace(hexKey))
	if err != nil {
		return nil, fmt.Errorf("failed to decode public key hex: %w", err)
	}
	if len(key) != ed25519.PublicKeySize {
		return nil, fmt.Errorf("invalid public key length: got %d bytes, want %d", len(key), ed25519.PublicKeySize)
	}
	return ed25519.PublicKey(key), nil
}

// SetPublicKey overrides the embedded primary public key used for artifact verification.
// The key must be a hex-encoded Ed25519 public key (64 hex characters). Keys added with
// AddPublicKey stay trusted.
func SetPublicKey(hexKey string) error {
	key, err := decodePublicKey(hexKey)
	if err != nil {
		return err
	}
	keysMu.Lock()
	defer keysMu.Unlock()
	OmniviewPublicKeyHex = hexKey
	omniviewPublicKey = key
	return nil
}

// AddPublicKey adds a hex-encoded Ed25519 public key whose signatures are accepted in addition to the
// primary key. Adding a key that is already trusted is a no-op.
func AddPublicKey(hexKey string) error {
	key, err := decodePublicKey(hexKey)
	if err != nil {
		return err
	}
	keysMu.Lock()
	defer keysMu.Unlock()
	for _, k := range additionalKeys {
		if k.Equal(key) {
			return nil
		}
	}
	additionalKeys = append(additionalKeys, key)
	return nil
}

// TrustedPublicKeys returns the hex-encoded keys whose signatures are accepted: the primary key first,
// then the additional keys in the order they were added.
func TrustedPublicKeys() []string {
	keysMu.RLock()
	defer keysMu.RUnlock()
	out := make([]string, 0, 1+len(additionalKeys))
	out = append(out, hex.EncodeToString(omniviewPublicKey))
	for _, k := range additionalKeys {
		out = append(out, hex.EncodeToString(k))
	}
	return out
}

// VerifyArtifactSignature verifies that the given checksum was signed by the primary key or one of the
// additional trusted keys.
func VerifyArtifactSignature(checksum, signatureB64 string) error {
	if signatureB64 == "" {
		return ErrUnsignedArtifact
	}

	sig, err := base64.StdEncoding.DecodeString(signatureB64)
	if err != nil {
		return fmt.Errorf("%w: malformed base64: %v", ErrInvalidSignature, err)
	}

	keysMu.RLock()
	defer keysMu.RUnlock()
	if ed25519.Verify(omniviewPublicKey, []byte(checksum), sig) {
		return nil
	}
	for _, k := range additionalKeys {
		if ed25519.Verify(k, []byte(checksum), sig) {
			return nil
		}
	}
	return ErrInvalidSignature
}
